export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Check for missing fields
  for (const field of ['a', 'b', 'operation']) {
    if (!(field in args)) {
      throw new Error(`Missing required field: ${field}`);
    }
  }

  // Check for extra fields
  for (const key of Object.keys(args)) {
    if (!VALID_FIELDS.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  // Validate types
  if (typeof args.a !== 'number') {
    throw new Error('Field a must be a number');
  }
  if (typeof args.b !== 'number') {
    throw new Error('Field b must be a number');
  }

  // Validate operation
  if (!OPERATIONS.has(args.operation)) {
    throw new Error(`Unsupported operation: ${args.operation}`);
  }

  // Division by zero
  if (args.operation === 'divide' && args.b === 0) {
    throw new Error('Division by zero');
  }

  let result;
  switch (args.operation) {
    case 'add':
      result = args.a + args.b;
      break;
    case 'subtract':
      result = args.a - args.b;
      break;
    case 'multiply':
